  0 <= bs < 2^64 -> 0 <= ioc < 2^64 -> 0 <= D < 2^64 -> 0 <= N < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + ASTREAM_CTOR_STACK <= bv_unsigned sp -> aceil <= lo -> mem_inv asegs m ->
  bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffff -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> stack0 m lo shi ->
  (forall (m2 : mem) (spa : Z) (gap : list cell) (p0 p8 p16 j16 j32 : list byte) (h3 : word) (ff fp : Z)
          (a3' a4' a5' a6' a7' t0' t1' t2' t3' t4' t5' t6' : word),
     rw_cells asegs m2 spa [CB 8 p0; CB 8 p8; CB 8 p16; C8 (Z_to_bv 64 ff)] ->
     rw_cells asegs m2 (spa + 32) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 32) ->
